#!/usr/bin/env python3
# apply_trade_replay_fix1.py — fence TRADE_REPLAY_FIX1_20260928
# (requires TRADE_REPLAY_20260928 — replaces its three files only if they are
#  byte-identical to what that script delivered; aborts otherwise)
#
# From the first screenshots of Trade Replay (28 Sep):
#   1. Entry not visible on some positional holds. Two causes fixed:
#      - the window was built from SPOT sessions only; a session missing from
#        the spot frame (special / Saturday sessions, gaps) dropped the
#        positional trade's ENTRY day, so the chart opened after the entry.
#        Now: spot sessions ∪ every day a leg printed ∪ entry and exit days
#        (a day without spot shows the contract only, with a note); any marker
#        that still falls outside the drawn sessions is named in the notes.
#      - short trades drew their entry/SL/TP lines only between entry and exit
#        (2 minutes ≈ 2 px): level lines now get a visible stub.
#   2. Exit price shown: an "exit" level (entry → exit, green/red by the leg's
#      result) with its axis label, and price tags on the markers of BOTH panes
#      ("sell 181.60 13:26", "exit 203.39 SL 13:28"; spot pane "entry 23915.40",
#      "exit …"); the spot pane now also marks the exit. Axis labels that
#      coincide (SL = exit on a stop-out) are nudged apart instead of overlapping.
#   3. Choices remembered: underlying and premium timeframes, HA on/off and the
#      lower-pane choice (Basket / main leg / the leg with the same tag or side /
#      signal contract) persist across Prev/Next and re-opening, per strategy
#      (localStorage scalp.replay.prefs.<STRATEGY>).
#
#   backend  app/backtest/replay/replay_core.py, test_trade_replay.py (165 checks;
#            new: a POSITIONAL TMA_V2 run — markers inside the window, exit
#            levels, entry day kept when its spot session is missing)
#   frontend components/replay/TradeReplay.jsx
#
# Deploy: ./desktop/build-scalp.sh both
#
# Run ONLY this script:
#   cd /Users/anbu/dev/scalp-app && python3 apply_trade_replay_fix1.py [--skip-tests]
from __future__ import annotations
import base64, hashlib, os, py_compile, shutil, subprocess, sys, tempfile

FENCE = "TRADE_REPLAY_FIX1_20260928"
PARENT = "TRADE_REPLAY_20260928"
ROOT = os.path.dirname(os.path.abspath(__file__))
MIRRORS = (("backend/app", "desktop/src-tauri/backend/app"), ("frontend/src", "desktop/src-tauri/frontend/src"))
OLD_SHA = {"backend/app/backtest/replay/replay_core.py": "c0fc60e8954000635f13bddb3fdfd288498292b7daffe35c5c48273229c8bb91", "backend/app/backtest/replay/test_trade_replay.py": "1b9d07463b2149a0266dfd3aa214d8e34f98f618b20442cddcc1b822acb54a7d", "frontend/src/components/replay/TradeReplay.jsx": "df8c4d7d9a434d1ca77c13a452b172ad3e8b9ce4cc18093620b5ccf18c3f1211"}
NEW = {"backend/app/backtest/replay/replay_core.py": "", "backend/app/backtest/replay/test_trade_replay.py": "", "frontend/src/components/replay/TradeReplay.jsx": ""}


def die(m):
    print("\nABORT:", m); sys.exit(1)


def mirror_of(rel):
    for src, dst in MIRRORS:
        if rel.startswith(src + "/"):
            root = os.path.join(ROOT, dst)
            return os.path.join(root, rel[len(src) + 1:]) if os.path.isdir(root) else None
    return None


print(f"── {FENCE}")
for rel, sha in OLD_SHA.items():
    p = os.path.join(ROOT, rel)
    if not os.path.exists(p):
        die(f"{rel} missing — apply apply_trade_replay.py ({PARENT}) first")
    raw = open(p, "rb").read()
    txt = raw.decode("utf-8")
    if FENCE in txt:
        die(f"{FENCE} already applied ({rel})")
    if PARENT not in txt:
        die(f"{rel} does not carry {PARENT}")
    if hashlib.sha256(raw).hexdigest() != sha:
        die(f"{rel} differs from what {PARENT} delivered (edited by hand?) — not overwriting; send me the file")

tmp = tempfile.mkdtemp(prefix="trade_replay_fix1_")
for rel, b64 in NEW.items():
    if rel.endswith(".py"):
        p = os.path.join(tmp, os.path.basename(rel))
        open(p, "wb").write(base64.b64decode(b64))
        try:
            py_compile.compile(p, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"py_compile failed for {rel}: {e}")
shutil.rmtree(tmp, ignore_errors=True)
print("   py_compile ok")

written = []
for rel, b64 in NEW.items():
    p = os.path.join(ROOT, rel)
    shutil.copy2(p, p + f".bak-{FENCE}")
    data = base64.b64decode(b64)
    open(p, "wb").write(data)
    written.append(rel)
    m = mirror_of(rel)
    if m and os.path.isdir(os.path.dirname(m)):
        open(m, "wb").write(data)
open(os.path.join(ROOT, f".{FENCE}.done"), "w").write("applied\n")
print(f"   replaced {len(written)} files (backups .bak-{FENCE}; desktop trees mirrored where present)")


def rollback(reason):
    for rel in written:
        p = os.path.join(ROOT, rel)
        shutil.move(p + f".bak-{FENCE}", p)
        m = mirror_of(rel)
        if m and os.path.isdir(os.path.dirname(m)):
            shutil.copy2(p, m)
    os.remove(os.path.join(ROOT, f".{FENCE}.done"))
    die(reason)


if "--skip-tests" not in sys.argv:
    env = dict(os.environ, PYTHONPATH=os.path.join(ROOT, "backend"))
    s = "app/backtest/replay/test_trade_replay.py"
    print("   running the replay suite (real runners on a synthetic corpus, ~1 min)…")
    r = subprocess.run([sys.executable, s], cwd=os.path.join(ROOT, "backend"), env=env, capture_output=True, text=True, timeout=1500)
    tail = (r.stdout.strip().splitlines() or [""])[-1]
    print(f"   {'ok  ' if r.returncode == 0 else 'FAIL'} {s} — {tail[:90]}")
    if r.returncode != 0:
        print("\n".join(l for l in r.stdout.splitlines() if "FAIL" in l)[-3000:])
        print((r.stderr or "")[-2000:])
        rollback("replay suite failed; working copy restored")
esb = os.path.join(ROOT, "frontend", "node_modules", ".bin", "esbuild")
esb = os.environ.get("ESBUILD") or (esb if os.path.exists(esb) else shutil.which("esbuild"))
if esb:
    rel = "frontend/src/components/replay/TradeReplay.jsx"
    r = subprocess.run([esb, rel, "--loader:.jsx=jsx", "--jsx=automatic", "--log-level=error", "--outfile=/dev/null"],
                       cwd=ROOT, capture_output=True, text=True)
    if r.returncode != 0:
        rollback("esbuild parse failed; restored:\n" + r.stderr[-1500:])
    print(f"   esbuild ok {rel}")
else:
    print("   (esbuild not found — JSX parse check skipped; the build will catch syntax)")
print(f"── {FENCE} applied. Next: ./desktop/build-scalp.sh both")
